package tool

// Staging Quality Intelligence - Auto-Generated / Artifact / Vendored File Detection
//
// Problem: AI agents frequently stage files that shouldn't be committed:
//   - Build artifacts (dist/, build/, bin/, target/, out/)
//   - Auto-generated code (.pb.go, _generated.go, .min.js, Code generated by...)
//   - Vendored dependencies (vendor/, node_modules/, third_party/)
//   - Binary/executable files (.exe, .so, .dylib, .wasm)
//   - IDE/editor artifacts (.DS_Store, .idea/, .vscode/settings.json)
//   - OS-generated files (Thumbs.db, desktop.ini)
//
// These files pollute the git history, inflate repo size, and cause merge
// conflicts. They should be in .gitignore, not in commits.
//
// Competitor analysis:
//   - GitHub Copilot: no detection - relies on .gitignore
//   - Cursor: no detection
//   - Claude Code: no detection
//   - Aider: auto-adds files but doesn't warn about artifacts
//   - Husky/pre-commit framework: catches some via hook config, but not AI-aware
//
// Gap: No existing ggcode check covers this. The diff scan (diff_scan.go) checks
// ADDED LINE CONTENT for debug statements and secrets. The critical_file check
// warns when editing infrastructure files. But neither detects when the staged
// FILE ITSELF is a generated artifact that shouldn't be committed at all.
//
// This check analyzes staged file PATHS (not content) against known artifact
// patterns. Zero LLM cost, fully deterministic, non-blocking advisory.

import (
	"fmt"
	"path/filepath"
	"strings"
)

// maxStagingWarnings caps the number of files listed to avoid overwhelming context.
const maxStagingWarnings = 10

// StagingIssue categorizes a file that probably shouldn't be committed.
type StagingIssue struct {
	Path     string
	Category string // "build-artifact", "generated", "vendored", "binary", "os-artifact", "ide-artifact"
	Reason   string
}

// generatedFilePatterns matches file names that are typically auto-generated.
var generatedFilePatterns = []struct {
	pattern string
	reason  string
}{
	{".min.js", "minified JavaScript (generated by build tools)"},
	{".min.css", "minified CSS (generated by build tools)"},
	{".pb.go", "Protobuf-generated Go code"},
	{".pb.validate.go", "Protobuf validation generated code"},
	{".gen.go", "code-generated Go file"},
	{"_generated.go", "generated Go file"},
	{".generated.ts", "generated TypeScript file"},
	{".generated.js", "generated JavaScript file"},
	{"_generated.py", "generated Python file"},
	{".g.dart", "generated Dart file (freezed/json_serializable)"},
	{".freezed.dart", "generated Dart file (freezed)"},
	{".mocks.dart", "generated Dart mocks"},
	{".pb.dart", "Protobuf-generated Dart"},
	{".grpc.pb.go", "gRPC-generated Go code"},
	{".deepcopy.go", "k8s deepcopy-generated Go code"},
	{".zz_generated.go", "k8s-generated Go code"},
	{"Wire.swift", "Swift DI generated file"},
	{".h.swift", "Swift bridging header (generated)"},
}

